Evictions During the Winter Months (November 1 - April 15)

Eviction filings


Code
filings_20_25 &lt;- filings_20_25 |&gt; 
  mutate(winter_season = case_when(month(fileddate) &gt;= 11 ~ TRUE,
                                   month(fileddate) &lt; 4 ~ TRUE,
                                   month(fileddate) == 4 & day(fileddate) &lt;= 15 ~ TRUE,
                                   .default = FALSE
                                   ))

winter_filings_table &lt;- filings_20_25 |&gt; 
  group_by(filed_year = year(fileddate)) |&gt; 
  summarize(all_filings = n(),
            winter_filings = sum(winter_season)) |&gt; 
  mutate(winter_filing_pct = round((winter_filings/all_filings*100), 1)) |&gt; 
  flextable() |&gt; 
  set_table_properties(width = 1, layout = "autofit") |&gt; 
  set_header_labels(
    filed_year = "Year",
    all_filings = "Annual Filings",
    winter_filings = "Winter Filings",
    winter_filing_pct = "Winter Filing Percentage (%)"
  ) |&gt; 
  colformat_num(j=1,
                big.mark = "") |&gt; 
  colformat_int(j=2:3,
                big.mark = ",") |&gt; 
  align(j=1,
      align = "left",
      part = "all")

