Compiling filings, executions, winter filings, and winter executions for the two political districts plus NYC Council districts:


Code
# Compile filings, executions, winter filings, winter executions for all political districts
filings_20_25_sf &lt;- filings_20_25_sf |&gt; 
  mutate(winter_season = case_when(month(fileddate) &gt;= 11 ~ TRUE,
                                   month(fileddate) &lt; 4 ~ TRUE,
                                   month(fileddate) == 4 & day(fileddate) &lt;= 15 ~ TRUE,
                                   .default = FALSE
                                   ))

executions_20_25_sf &lt;- executions_20_25_sf |&gt; 
  mutate(winter_season = case_when(month(executiondate) &gt;= 11 ~ TRUE,
                                   month(executiondate) &lt; 4 ~ TRUE,
                                   month(executiondate) == 4 & day(executiondate) &lt;= 15 ~ TRUE,
                                   .default = FALSE
                                   ))

### Assembly Districts ###
nysad_compiled &lt;- nysad |&gt; 
  select(District, Name, Party) |&gt; 
  mutate(Region = case_when(District %in% nysad_upstate$District ~ "Upstate",
                            District %in% nysad_downstate$District ~ "Downstate",
                            .default = NA))

executions_20_25_nysad &lt;- executions_20_25_sf |&gt; 
  st_join(nysad_compiled |&gt; select(District))



nysad_compiled &lt;- nysad_compiled |&gt; 
  left_join(
    bind_rows(
      nysad_downstate_5year,
      nysad_upstate_5year
    ) |&gt; 
      rename("filings_20_25" = "Eviction Filings") |&gt; 
      select(!Name),
    by = join_by(District)
  ) |&gt; 
  left_join(
    bind_rows(
      nysad_downstate_1year,
      nysad_upstate_1year
    ) |&gt; 
      rename("filings_25" = "Eviction Filings") |&gt; 
      select(!Name),
    by = join_by(District)
  ) |&gt; 
  left_join(executions_20_25_nysad |&gt; 
              st_drop_geometry() |&gt; 
              group_by(District) |&gt; 
              summarize(executions_20_25 = n())) |&gt; 
  left_join(executions_20_25_nysad |&gt; 
              filter(year(executiondate) == 2025) |&gt; 
              st_drop_geometry() |&gt; 
              group_by(District) |&gt; 
              summarize(executions_25 = n())) |&gt; 
  left_join(filings_20_25_sf |&gt; 
              filter(winter_season == TRUE) |&gt; 
              st_join(nysad_compiled |&gt; select(District)) |&gt;
              st_drop_geometry() |&gt; 
              group_by(District) |&gt; 
              summarize(winter_filings_20_25 = n())) |&gt; 
  left_join(filings_20_25_sf |&gt; 
              filter(winter_season == TRUE & year(fileddate) == 2025) |&gt; 
              st_join(nysad_compiled |&gt; select(District)) |&gt;
              st_drop_geometry() |&gt; 
              group_by(District) |&gt; 
              summarize(winter_filings_25 = n())) |&gt; 
  left_join(executions_20_25_nysad |&gt; 
              filter(winter_season == TRUE) |&gt; 
              st_drop_geometry() |&gt; 
              group_by(District) |&gt; 
              summarize(winter_executions_20_25 = n())) |&gt; 
  left_join(executions_20_25_nysad |&gt; 
              filter(winter_season == TRUE & year(executiondate) == 2025) |&gt; 
              st_drop_geometry() |&gt; 
              group_by(District) |&gt; 
              summarize(winter_executions_25 = n())) |&gt; 
  st_drop_geometry()

# Rearrange
nysad_compiled &lt;- nysad_compiled |&gt; 
  relocate(contains("20_25"),
           .after = Region)

### Senate Districts ###
nyss_compiled &lt;- nyss |&gt; 
  select(DISTRICT, NAME, Party) |&gt; 
  mutate(Region = case_when(DISTRICT %in% nyss_upstate$DISTRICT ~ "Upstate",
                            DISTRICT %in% nyss_downstate$DISTRICT ~ "Downstate",
                            .default = NA))

executions_20_25_nyss &lt;- executions_20_25_sf |&gt; 
  st_join(nyss_compiled |&gt; select(DISTRICT))

nyss_compiled &lt;- nyss_compiled |&gt; 
  left_join(
    bind_rows(
      nyss_upstate_5year,
      nyss_downstate_5year
    ) |&gt; 
      rename("filings_20_25" = "Eviction Filings") |&gt; 
      select(!NAME),
    by = join_by(DISTRICT)
  ) |&gt; 
  left_join(
    bind_rows(
      nyss_downstate_1year,
      nyss_upstate_1year
    ) |&gt; 
      rename("filings_25" = "Eviction Filings") |&gt; 
      select(!NAME),
    by = join_by(DISTRICT)
  ) |&gt; 
  left_join(executions_20_25_nyss |&gt; 
              st_drop_geometry() |&gt; 
              group_by(DISTRICT) |&gt; 
              summarize(executions_20_25 = n())) |&gt; 
  left_join(executions_20_25_nyss |&gt; 
              filter(year(executiondate) == 2025) |&gt; 
              st_drop_geometry() |&gt; 
              group_by(DISTRICT) |&gt; 
              summarize(executions_25 = n())) |&gt; 
  left_join(filings_20_25_sf |&gt; 
              filter(winter_season == TRUE) |&gt; 
              st_join(nyss_compiled |&gt; select(DISTRICT)) |&gt;
              st_drop_geometry() |&gt; 
              group_by(DISTRICT) |&gt; 
              summarize(winter_filings_20_25 = n())) |&gt; 
  left_join(filings_20_25_sf |&gt; 
              filter(winter_season == TRUE & year(fileddate) == 2025) |&gt; 
              st_join(nyss_compiled |&gt; select(DISTRICT)) |&gt;
              st_drop_geometry() |&gt; 
              group_by(DISTRICT) |&gt; 
              summarize(winter_filings_25 = n())) |&gt; 
  left_join(executions_20_25_nyss |&gt; 
              filter(winter_season == TRUE) |&gt; 
              st_drop_geometry() |&gt; 
              group_by(DISTRICT) |&gt; 
              summarize(winter_executions_20_25 = n())) |&gt; 
  left_join(executions_20_25_nyss |&gt; 
              filter(winter_season == TRUE & year(executiondate) == 2025) |&gt; 
              st_drop_geometry() |&gt; 
              group_by(DISTRICT) |&gt; 
              summarize(winter_executions_25 = n())) |&gt; 
  st_drop_geometry()

# Rearrange
nyss_compiled &lt;- nyss_compiled |&gt; 
  relocate(contains("20_25"),
           .after = Region)


### NYC Council ###
nyc_council &lt;- nyc_council |&gt; 
  select(CounDist, name) |&gt; 
  arrange(CounDist)

filings_20_25_nycc &lt;- filings_20_25_sf |&gt; 
  st_join(nyc_council |&gt; select(CounDist)) |&gt; 
  st_drop_geometry()

executions_20_25_nycc &lt;- executions_20_25_sf |&gt; 
  st_join(nyc_council |&gt; select(CounDist)) |&gt; 
  st_drop_geometry()

nyc_council_compiled &lt;- nyc_council |&gt; 
  # Filings 20-25
  left_join(filings_20_25_nycc |&gt; 
              filter(!is.na(CounDist)) |&gt; 
              group_by(CounDist) |&gt; 
              summarize(filings_20_25 = n())) |&gt; 
  # Executions 20-25
  left_join(executions_20_25_nycc |&gt; 
              filter(!is.na(CounDist)) |&gt; 
              group_by(CounDist) |&gt; 
              summarize(executions_20_25 = n())) |&gt; 
  # Winter filings 20-25
  left_join(filings_20_25_nycc |&gt; 
              filter(!is.na(CounDist) & winter_season == TRUE) |&gt; 
              group_by(CounDist) |&gt; 
              summarize(winter_filings_20_25 = n())) |&gt; 
  # Winter Executions 20-25
  left_join(executions_20_25_nycc |&gt; 
              filter(!is.na(CounDist) & winter_season == TRUE) |&gt; 
